 async function ensure(id,piece,body){if(piece==='original'||!pieces.includes(piece))return true;const r=rig(id);if(!r)return false;const v=body?r.variants[variant(body)]:r.variants.base,p=manifest.parts[r.race+':'+piece];if(!v||body&&v.bodyHash!==body.sha256)throw Error('Equipment source changed; refit required');try{await Promise.all([image(v.mask,v.maskHash),image(p.atlas,p.sha256)]);failures.delete(canonical(id)+':'+variant(body||{})+':'+piece);return true}catch(e){failures.set(canonical(id)+':'+variant(body||{})+':'+piece,String(e.message||e));throw e}}
