async function open(base){if(active)return active;if(opening)return opening;opening=(async()=>{const response=await root.fetch(new URL('assets/fitted-equipment-v1/manifest.json?v=p21-b407-s039-reuse',base));if(!response.ok)throw Error('Fitted armour catalogue unavailable');active=create(await response.json(),{baseURL:base});return active})().catch(e=>{opening=null;throw e});return opening}
